import { signal } from '@angular/core';
import { TestBed } from '@angular/core/testing';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { AuthPort, SessionState } from '../auth/auth.port';
import { PORTAL_FETCH, RuntimeConfigService, RuntimePublicConfig } from '../auth/runtime-config';
import { BriefClient } from './brief.client';
import { BriefEditorStore } from './brief-editor.store';
// Generated by services/gcsp-api BriefJavaGoldenTest from the real BriefService and BriefResource.respond; never edited by hand.
import manifest from '../../../../../services/gcsp-api/src/test/resources/brief/java-golden/manifest.json';
import editorInitial from '../../../../../services/gcsp-api/src/test/resources/brief/java-golden/01-editor-initial.json';
import preferencesSave from '../../../../../services/gcsp-api/src/test/resources/brief/java-golden/02-preferences-save.json';
import editorAfterSave from '../../../../../services/gcsp-api/src/test/resources/brief/java-golden/03-editor-after-save.json';
import draftSave from '../../../../../services/gcsp-api/src/test/resources/brief/java-golden/04-draft-save.json';
import confirmWithConsent from '../../../../../services/gcsp-api/src/test/resources/brief/java-golden/05-confirm-with-consent.json';
import editorConfirmed from '../../../../../services/gcsp-api/src/test/resources/brief/java-golden/06-editor-confirmed.json';
import pauseSearch from '../../../../../services/gcsp-api/src/test/resources/brief/java-golden/07-pause-search.json';
import editorPaused from '../../../../../services/gcsp-api/src/test/resources/brief/java-golden/08-editor-paused.json';
import preferencesStale from '../../../../../services/gcsp-api/src/test/resources/brief/java-golden/09-preferences-stale.json';
import editorUnavailable from '../../../../../services/gcsp-api/src/test/resources/brief/java-golden/10-editor-unavailable.json';
import preferencesUnavailable from '../../../../../services/gcsp-api/src/test/resources/brief/java-golden/11-preferences-unavailable.json';

interface Step {
  readonly file: string; readonly step: string; readonly method: 'GET' | 'POST'; readonly path: string;
  readonly request: Record<string, unknown> | null; readonly status: number;
  readonly body: { readonly status: string; readonly value?: Record<string, any>; readonly [key: string]: unknown };
}
interface Manifest {
  readonly basePath: string; readonly scope: { readonly environmentId: string; readonly runId: string; readonly employeeId: string; readonly principalId: string; readonly policyVersion: string };
  readonly steps: readonly { readonly file: string; readonly step: string; readonly method: string; readonly path: string; readonly status: number }[];
}
const steps: readonly Step[] = [editorInitial, preferencesSave, editorAfterSave, draftSave, confirmWithConsent, editorConfirmed, pauseSearch,
  editorPaused, preferencesStale, editorUnavailable, preferencesUnavailable].map((s) => structuredClone(s) as unknown as Step);
const index = Object.fromEntries(steps.map((s) => [s.step, s])) as Record<string, Step>;
const plan = manifest as unknown as Manifest;
const value = (name: string): Record<string, any> => structuredClone(index[name].body.value!);
const base = `https://api.example${plan.basePath}`;
const TOKEN = 'token-employee';

describe('preferences client and store over the Java brief goldens', () => {
  let state: ReturnType<typeof signal<SessionState>>;
  let queue: Map<string, Step[]>;
  let requests: { method: string; path: string; search: string; token: string | null; body: unknown }[];
  const serve = (...names: string[]) => { for (const name of names) { const s = index[name]; const key = `${s.method} ${s.path}`; queue.set(key, [...(queue.get(key) ?? []), s]); } };
  const posts = (path: string) => requests.filter((r) => r.method === 'POST' && r.path === path);
  const idle = async () => { for (let round = 0; round < 40; round++) { await new Promise<void>((resolve) => setTimeout(resolve, 0)); TestBed.tick(); } };

  beforeEach(() => {
    queue = new Map(); requests = [];
    state = signal<SessionState>({ status: 'signed-out' });
    const config: RuntimePublicConfig = { schemaVersion: 1, environmentId: plan.scope.environmentId, apiBaseUrl: base,
      oidc: { authority: 'https://issuer.example', clientId: 'public-client', scope: 'openid', redirectUri: 'https://portal.example/gcsp/auth/callback', postLogoutRedirectUri: 'https://portal.example/gcsp/' } };
    // Like Java, the fake server knows the caller only from the bearer token and replays the recorded reply for each route.
    const fetcher = vi.fn(async (input: RequestInfo | URL, init?: RequestInit) => {
      const url = new URL(String(input)); const path = url.pathname.slice(plan.basePath.length);
      const token = new Headers(init?.headers).get('Authorization')?.replace(/^Bearer /, '') ?? null;
      requests.push({ method: init?.method ?? 'GET', path, search: url.search, token, body: init?.body ? JSON.parse(String(init.body)) : undefined });
      if (token !== TOKEN) return new Response(JSON.stringify({ status: 'unauthenticated', code: 'authentication-required' }), { status: 401 });
      const next = queue.get(`${init?.method ?? 'GET'} ${path}`)?.shift();
      if (!next) return new Response(JSON.stringify({ status: 'not-found', code: 'route-not-found' }), { status: 404 });
      return new Response(JSON.stringify(next.body), { status: next.status, headers: { 'Content-Type': 'application/json' } });
    });
    TestBed.configureTestingModule({ providers: [
      { provide: AuthPort, useValue: { state, recovery: signal(null), getAccessToken: async () => (state().status === 'ready' ? TOKEN : null), signIn: vi.fn(), retry: vi.fn() } },
      { provide: RuntimeConfigService, useValue: { load: async () => config } },
      { provide: PORTAL_FETCH, useValue: fetcher }] });
  });
  afterEach(() => vi.restoreAllMocks());

  const signIn = () => state.set({ status: 'ready', context: { subject: plan.scope.principalId, roles: ['employee'], environmentId: plan.scope.environmentId,
    runId: plan.scope.runId, employeeId: plan.scope.employeeId, policyVersion: plan.scope.policyVersion, capabilities: [] } });
  const openStore = async (...names: string[]) => { serve(...names); signIn(); const store = TestBed.inject(BriefEditorStore); TestBed.tick(); await idle(); return store; };
  const ownedRequests = () => {
    expect(requests.length).toBeGreaterThan(0);
    for (const r of requests) {
      expect(r.token).toBe(TOKEN); expect(r.search).toBe(''); expect(r.path).not.toContain(plan.scope.employeeId);
      expect(JSON.stringify(r.body ?? {})).not.toMatch(/"(employeeId|runId|environmentId|principalId|subject)"/);
    }
  };

  it('the manifest lists exactly these step files in order with their method, path and status', () => {
    expect(plan.steps.map((s) => s.file)).toEqual(steps.map((s) => s.file));
    for (const [i, s] of plan.steps.entries()) expect({ ...s }).toEqual({ file: steps[i].file, step: steps[i].step, method: steps[i].method, path: steps[i].path, status: steps[i].status });
  });

  it('the real client accepts every Java body and maps every Java refusal truthfully', async () => {
    signIn(); const client = TestBed.inject(BriefClient);
    for (const s of steps) {
      serve(s.step);
      const request = structuredClone(s.request) as never;
      const result = s.path === '/brief/editor' ? await client.readEditor()
        : s.path === '/brief/preferences' ? await client.savePreferences(request)
          : s.path === '/brief/draft' ? await client.saveDraft(request)
            : s.path === '/brief/confirm' ? await client.confirm(request)
              : s.path === '/brief/pause-search' ? await client.pauseSearch(request) : null;
      expect(result, s.step).not.toBeNull();
      const sent = requests.at(-1)!;
      expect(sent.method, s.step).toBe(s.method); expect(sent.path, s.step).toBe(s.path);
      if (s.request) expect(sent.body, s.step).toEqual(s.request);
      if (s.status === 200) expect(result, s.step).toEqual({ status: 'ok', value: s.body.value });
      else expect(result, s.step).toMatchObject({ status: s.body.status, code: s.body['code'] });
    }
    ownedRequests();
    expect(await client.readEditor()).toMatchObject({ status: 'not-found' });
  });

  it('opens with the server context and all four versions as Java sent them', async () => {
    const store = await openStore('editor-initial');
    const java = value('editor-initial');
    expect(store.editor()?.versions).toEqual(java['versions']);
    expect(store.editor()?.context.contextVersion).toBe(java['versions']['context']);
    expect(store.briefVersion()).toBe(java['initial']['briefVersion']); expect(store.draftVersion()).toBe(java['initial']['draftVersion']);
    expect(store.editor()?.initial.buddy).toEqual(java['initial']['buddy']);
    expect(store.failure()).toBeNull(); ownedRequests();
  });

  it('saves, adopts the server readback and a reload shows the server saved version', async () => {
    const store = await openStore('editor-initial', 'preferences-save', 'editor-after-save');
    const contractId = value('editor-initial')['initial']['currentCarRating']['contractId'];
    store.rate(4, contractId); await idle();
    const sent = posts('/brief/preferences');
    expect(sent).toHaveLength(1);
    expect(sent[0].body).toMatchObject({ expectedBriefVersion: 0, expectedDraftVersion: 0, currentCarRating: { contractId, value: 4 } });
    const saved = value('preferences-save');
    expect(store.draftVersion()).toBe(saved['draftVersion']); expect(store.rating()).toEqual(saved['currentCarRating']);
    expect(store.categories()).toEqual(saved['accountPreferences']['categories']);
    expect(store.message()).toBe('Preferences saved automatically.');

    await store.reload(); await idle();
    const reloaded = value('editor-after-save');
    expect(store.editor()?.versions).toEqual(reloaded['versions']);
    expect(store.draftVersion()).toBe(reloaded['initial']['draftVersion']); expect(store.rating()).toEqual(reloaded['initial']['currentCarRating']);
    expect(store.categories()).toEqual(reloaded['initial']['accountPreferences']['categories']);
    expect(store.understanding()?.value).toBe(reloaded['initial']['accountPreferences']['understanding']['value']);
    ownedRequests();
  });

  it('pausing search shows the Buddy state the server returned, and the refreshed read agrees', async () => {
    const store = await openStore('editor-confirmed', 'pause-search', 'editor-paused');
    const confirmed = value('editor-confirmed');
    expect(store.editor()?.initial.buddy.state).toBe('engaged');
    await store.runBuddyCommand('pauseSearch'); await idle();
    const sent = posts('/brief/pause-search');
    expect(sent).toHaveLength(1);
    expect(sent[0].body).toMatchObject({ expectedBriefVersion: confirmed['initial']['briefVersion'], expectedDraftVersion: confirmed['initial']['draftVersion'] });
    const paused = value('pause-search');
    expect(store.editor()?.initial.buddy).toEqual(paused['buddy']); expect(store.briefVersion()).toBe(paused['briefVersion']);
    expect(store.buddyMessage()).toBe('Search paused. New searches and holds have stopped. Any held offer stays open until its deadline.');

    await store.reloadBuddyStatus(); await idle();
    expect(store.editor()?.initial.buddy).toEqual(value('editor-paused')['initial']['buddy']);
    expect(store.editor()?.versions).toEqual(value('editor-paused')['versions']);
    ownedRequests();
  });

  it('a stale save keeps the edit, asks for a reload and sends nothing more until then', async () => {
    const store = await openStore('editor-paused', 'preferences-stale', 'editor-paused');
    store.change('size', { value: 100 }); await idle();
    expect(store.failure()).toMatchObject({ status: 'stale-version', code: 'stale-version', action: 'refresh' });
    expect(store.message()).toBe('Your preferences changed elsewhere. Reload to see the latest. Your edits are kept until then.');
    expect(store.category('size')).toMatchObject({ state: 'considered', value: 100 }); expect(store.locked()).toBe(true);
    store.retry(); store.change('size', { value: 0 }); await idle();
    expect(posts('/brief/preferences')).toHaveLength(1);

    await store.reload(); await idle();
    expect(store.failure()).toBeNull();
    expect(store.categories()).toEqual(value('editor-paused')['initial']['accountPreferences']['categories']);
    ownedRequests();
  });

  it('an unavailable save keeps the edit, says it is not confirmed and does not retry by itself', async () => {
    const store = await openStore('editor-paused', 'preferences-unavailable');
    store.change('size', { value: 100 }); await idle();
    expect(store.failure()).toMatchObject({ status: 'unavailable', code: 'brief-unavailable' });
    expect(store.message()).toBe('Your changes are not confirmed as saved. Try again or reload.');
    expect(store.category('size')).toMatchObject({ state: 'considered', value: 100 });
    expect(posts('/brief/preferences')).toHaveLength(1);
    expect(store.draftVersion()).toBe(value('editor-paused')['initial']['draftVersion']);
    ownedRequests();
  });

  it('an unavailable editor read shows no editor and no invented state', async () => {
    const store = await openStore('editor-unavailable');
    expect(store.editor()).toBeNull();
    expect(store.failure()).toMatchObject({ status: 'unavailable', code: 'brief-unavailable' });
    expect(store.message()).toBe('Your preferences could not be loaded. Try again.');
    expect(store.categories()).toEqual({}); expect(store.rating()).toBeNull();
    ownedRequests();
  });
});
